from __future__ import annotations
import base64, subprocess, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parent
APP = ROOT / "source" / "app"
MAIN = APP / "main.py"
INIT = APP / "astrostack" / "__init__.py"
MAIN_WINDOW = APP / "astrostack" / "gui" / "main_window.py"
UX14 = APP / "astrostack" / "gui" / "ux_v14.py"
TEST = APP / "tests" / "test_ux_v14.py"
UX14_CONTENT = base64.b64decode("").decode("utf-8")
TEST_CONTENT = base64.b64decode("").decode("utf-8")
RAW_FIXED = base64.b64decode("").decode("utf-8")

def run(*args):
    return subprocess.run(list(args), cwd=ROOT, text=True, capture_output=True)

def branch():
    r = run("git", "branch", "--show-current")
    return r.stdout.strip() if r.returncode == 0 else ""

def ensure_branch():
    b = branch()
    if b == "astrostack-1.4-ui": return
    if b != "astrostack-1.3.3": raise RuntimeError(f"Branch attuale: {b!r}. Passa prima ad astrostack-1.3.3.")
    exists = run("git", "show-ref", "--verify", "--quiet", "refs/heads/astrostack-1.4-ui").returncode == 0
    r = run("git", "checkout", "astrostack-1.4-ui") if exists else run("git", "checkout", "-b", "astrostack-1.4-ui")
    if r.returncode != 0: raise RuntimeError(r.stderr)

def backup(path):
    if path.is_file():
        dest = path.with_name(path.name + ".v14.bak")
        if not dest.exists(): dest.write_text(path.read_text(encoding="utf-8-sig"), encoding="utf-8")

def main():
    if not (ROOT / ".git").exists():
        print("ERRORE: metti questo file nella root del repository AstroStack.")
        return 2
    try:
        ensure_branch()
        backup(INIT); INIT.write_text('"""AstroStack."""\n__version__ = "1.4.0-preview"\n', encoding="utf-8")
        backup(MAIN)
        text = MAIN.read_text(encoding="utf-8-sig")
        if "ux_v14" not in text:
            needle = "    from astrostack.gui.ux_v13 import install as install_ux_v13\n"
            if needle not in text: raise RuntimeError("Import ux_v13 non trovato in main.py")
            text = text.replace(needle, needle + "    from astrostack.gui.ux_v14 import install as install_ux_v14\n", 1)
        if "install_ux_v14(win)" not in text:
            needle = "    install_ux_v13(win)\n"
            if needle not in text: raise RuntimeError("install_ux_v13(win) non trovato")
            text = text.replace(needle, needle + "    install_ux_v14(win)\n", 1)
        MAIN.write_text(text, encoding="utf-8")
        backup(MAIN_WINDOW)
        text = MAIN_WINDOW.read_text(encoding="utf-8-sig")
        start = "    def open_image_path(self, path: str):\n"
        end = "    # ------------------------------------------------------------ esportazione\n"
        a = text.find(start); b = text.find(end, a)
        if a < 0 or b < 0: raise RuntimeError("Blocco open_image_path non trovato")
        MAIN_WINDOW.write_text(text[:a] + RAW_FIXED + text[b:], encoding="utf-8")
        UX14.write_text(UX14_CONTENT, encoding="utf-8")
        TEST.write_text(TEST_CONTENT, encoding="utf-8")
        subprocess.check_call([sys.executable, "-m", "py_compile", str(MAIN), str(INIT), str(MAIN_WINDOW), str(UX14), str(TEST)], cwd=ROOT)
    except Exception as exc:
        print("ERRORE:", exc)
        return 3
    print("ASTROSTACK_140_UI_FILES_OK")
    print("Branch:", branch())
    print(r"Ora: cd source\app")
    print(r"Poi: python tests\test_ux_v14.py")
    print(r"Infine: Start-Process python -ArgumentList 'main.py'")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
